INTENTS = {
  "count": ["how many", "number of", "count"],
  "compare": ["compare", "versus", "difference between"],
  "lookup": ["find", "show", "what is", "locate"],
  "list": ["list", "show all", "every"],
}
def intent(q):
    q = q.lower()
    best, bs = "lookup", 0
    for name, pats in INTENTS.items():
        s = sum(1 for p in pats if p in q)
        if s > bs: best, bs = name, s
    return best
for q in ["How many patents mention lasers?", "Compare archive A and B", "Find the 1998 spec"]:
    print(repr(q[:32]), "->", intent(q))

