ALIASES = {"ai": ["artificial intelligence"], "find": ["locate", "search"],
           "db": ["database"], "ml": ["machine learning"]}
def expand(terms):
    out = []
    for t in terms:
        out.append(t)
        out.extend(a for a in ALIASES.get(t.lower(), []) if a not in out)
    return out
print(expand(["find", "AI", "records"]))

